Implement `_experimental_snapshot/2`

Enables writing to files from within jq scripts.

Resolves #3153

The scary name and lack of documentation should serve to inform users that its behavior is subject to breaking changes, and should therefore not be used in production scripts for the time being.

At the moment, this builtin performs a dry run by default. To actually write any data to disk, set the environment variable `JQ_ENABLE_SNAPSHOT=1`. A proper sandboxing interface is outside the scope of this PR, please refer to the link below instead:
* #3092

I've renamed this builtin to `snapshot/2` to highlight the fact that script execution is unaffected by the results of the file writing process (dry run, success, failure), allowing scripts that use it to remain constant and repeatable.

This allows the language to maintain referential transparency even when interacting with the outside world.

diff --git a/src/builtin.c b/src/builtin.c
index da4a770fac..29a6e4e21e 100644
--- a/src/builtin.c
+++ b/src/builtin.c
@@ -1346,7 +1346,38 @@ static jv f_input(jq_state *jq, jv input) {
     return v;
   return jv_invalid_with_msg(jv_string("break"));
 }
+static jv f_snapshot(jq_state *jq, jv input, jv filename, jv data) {
+  if (jv_get_kind(filename) != JV_KIND_STRING)
+    return ret_error(filename, jv_string("filename must be a string"));

+  const char *name_str = jv_string_value(filename);
+  int sandbox = 1;
+  {
+    // TODO: replace this when --sandbox is implemented
+    const char *disable_sandbox = getenv("JQ_ENABLE_SNAPSHOT");
+    if (disable_sandbox && *disable_sandbox)
+      sandbox = 0;
+  }
+  if (sandbox) {
+    fprintf(stderr, "jq: dry run: %s (set JQ_ENABLE_SNAPSHOT=1)\n", name_str);
+  } else {
+    FILE *fp = fopen(name_str, "wb");
+    if (!fp) {
+      //perror("fopen");
+      fprintf(stderr, "jq: error: could not open %s for writing\n", name_str);
+    } else {
+      if (jv_get_kind(data) == JV_KIND_STRING)
+        priv_fwrite(jv_string_value(data), jv_string_length_bytes(jv_copy(data)), fp, 0);
+      else
+        jv_dumpf(jv_copy(data), fp, JV_PRINT_ASCII);
+      fclose(fp);
+    }
+  }
+
+  jv_free(filename);
+  jv_free(data);
+  return input;
+}
 static jv f_debug(jq_state *jq, jv input) {
   jq_msg_cb cb;
   void *data;
