+  if(is_result_needed(ast) && !is_legal_dontcare_read(ast))
+  {
+    ast_error(opt->check.errors, ast, "can't read from '_'");
+    return false;
+  }
+
   ast_settype(ast, ast_from(ast, TK_DONTCARETYPE));

   return true;
