-        r_value = gen_unbox(c, type, r_value);
+        if(ast_id(type) == TK_TUPLETYPE)
+          r_value = gen_unbox(c, type, r_value);
+        else
+          return assign_union_to_tuple(c, l_type, r_value, type);
+
