+#ifndef SIMDJSON_DOCUMENT_PARSER_H
+#define SIMDJSON_DOCUMENT_PARSER_H
+
+#include <cstring>
+#include <memory>
+#include "simdjson/common_defs.h"
+#include "simdjson/simdjson.h"
+#include "simdjson/document.h"
