diff --git a/pkg/cmd/pr/shared/lister.go b/pkg/cmd/pr/shared/lister.go
new file mode 100644
index 00000000000..454ecbfcf8d
--- /dev/null
+++ b/pkg/cmd/pr/shared/lister.go
@@ -0,0 +1,196 @@
+package shared
+
+import (
+	"fmt"
+	"net/http"
+
+	"github.com/cli/cli/v2/internal/ghrepo"
+	"github.com/cli/cli/v2/pkg/cmdutil"
+
+	api "github.com/cli/cli/v2/api"
+)
+
+type PRLister interface {
+	List(opt ListOptions) (*api.PullRequestAndTotalCount, error)
+}
+
+type ListOptions struct {
+	LimitResults int
+
+	State      string
+	BaseBranch string
+	HeadBranch string
+
+	Fields []string
+}
+
+type lister struct {
+	baseRepoFn func() (ghrepo.Interface, error)
+	httpClient func() (*http.Client, error)
+}
+
+func NewLister(factory *cmdutil.Factory) PRLister {
+	return &lister{
+		baseRepoFn: factory.BaseRepo,
+		httpClient: factory.HttpClient,
+	}
+}
+
+func (l *lister) List(opts ListOptions) (*api.PullRequestAndTotalCount, error) {
+	repo, err := l.baseRepoFn()
+	if err != nil {
+		return nil, err
+	}
+
+	client, err := l.httpClient()
+	if err != nil {
+		return nil, err
+	}
+
+	return listPullRequests(client, repo, opts)
+}
+
+func listPullRequests(httpClient *http.Client, repo ghrepo.Interface, filters ListOptions) (*api.PullRequestAndTotalCount, error) {
+	type response struct {
+		Repository struct {
+			PullRequests struct {
+				Nodes    []api.PullRequest
+				PageInfo struct {
+					HasNextPage bool
+					EndCursor   string
+				}
+				TotalCount int
+			}
+		}
+	}
+	limit := filters.LimitResults
+	fragment := fmt.Sprintf("fragment pr on PullRequest{%s}", api.PullRequestGraphQL(filters.Fields))
+	query := fragment + `
+		query PullRequestList(
+			$owner: String!,
+			$repo: String!,
+			$limit: Int!,
+			$endCursor: String,
+			$baseBranch: String,
+			$headBranch: String,
+			$state: [PullRequestState!] = OPEN
+		) {
+			repository(owner: $owner, name: $repo) {
+				pullRequests(
+					states: $state,
+					baseRefName: $baseBranch,
+					headRefName: $headBranch,
+					first: $limit,
+					after: $endCursor,
+					orderBy: {field: CREATED_AT, direction: DESC}
+				) {
+					totalCount
+					nodes {
+						...pr
+					}
+					pageInfo {
+						hasNextPage
+						endCursor
+					}
+				}
+			}
+		}`
+
+	pageLimit := min(limit, 100)
+	variables := map[string]interface{}{
+		"owner": repo.RepoOwner(),
+		"repo":  repo.RepoName(),
+	}
+
+	switch filters.State {
+	case "open":
+		variables["state"] = []string{"OPEN"}
+	case "closed":
+		variables["state"] = []string{"CLOSED", "MERGED"}
+	case "merged":
+		variables["state"] = []string{"MERGED"}
+	case "all":
+		variables["state"] = []string{"OPEN", "CLOSED", "MERGED"}
+	default:
+		return nil, fmt.Errorf("invalid state: %s", filters.State)
+	}
+
+	if filters.BaseBranch != "" {
+		variables["baseBranch"] = filters.BaseBranch
+	}
+	if filters.HeadBranch != "" {
+		variables["headBranch"] = filters.HeadBranch
+	}
+
+	res := api.PullRequestAndTotalCount{}
+	var check = make(map[int]struct{})
+	client := api.NewClientFromHTTP(httpClient)
+
+loop:
+	for {
+		variables["limit"] = pageLimit
+		var data response
+		err := client.GraphQL(repo.RepoHost(), query, variables, &data)
+		if err != nil {
+			return nil, err
+		}
+		prData := data.Repository.PullRequests
+		res.TotalCount = prData.TotalCount
+
+		for _, pr := range prData.Nodes {
+			if _, exists := check[pr.Number]; exists && pr.Number > 0 {
+				continue
+			}
+			check[pr.Number] = struct{}{}
+
+			res.PullRequests = append(res.PullRequests, pr)
+			if len(res.PullRequests) == limit {
+				break loop
+			}
+		}
+
+		if prData.PageInfo.HasNextPage {
+			variables["endCursor"] = prData.PageInfo.EndCursor
+			pageLimit = min(pageLimit, limit-len(res.PullRequests))
+		} else {
+			break
+		}
+	}
+
+	return &res, nil
+}
+
+type mockLister struct {
+	called       bool
+	expectFields []string
+
+	result *api.PullRequestAndTotalCount
+	err    error
+}
+
+func NewMockLister(result *api.PullRequestAndTotalCount, err error) *mockLister {
+	return &mockLister{
+		result: result,
+		err:    err,
+	}
+}
+
+func (m *mockLister) List(opt ListOptions) (*api.PullRequestAndTotalCount, error) {
+	m.called = true
+	if m.err != nil {
+		return nil, m.err
+	}
+
+	if m.expectFields != nil {
+
+		if !isEqualSet(m.expectFields, opt.Fields) {
+			return nil, fmt.Errorf("unexpected fields: %v", opt.Fields)
+		}
+	}
+
+	return m.result, m.err
+}
+
+func (m *mockLister) ExpectFields(fields []string) {
+	m.expectFields = fields
+}

Add handling of empty titles for Issues and PRs

Closes #9698 

## Background

Currently, the prompter doesn't enforce the requirement of a title for PR and Issue creation. However, that creates the UX where a user can enter a blank title, spend time filling out a detailed body, then fail to create the issue or pr when the request is sent to the api because the title is blank. This attempts to handle that before sending a request to the api, enforcing that, when prompting, the title of an issue is not blank.

## Design

This was a relatively easy change to make. I've included a screenshot of the current design below (it matches what was suggested in #9698):

<img width="630" alt="Screenshot 2024-10-08 at 4 33 59 PM" src="https://github.com/user-attachments/assets/3fd48f8e-8577-4fa4-a119-736cc940fabc">

### Re-prompting vs exiting

**Current UX:** _User inputs blank title_ - prompts for the rest of the issue info then fails when issue is created:
**UX in this PR:** _User inputs blank title_ - gives error message and re-prompts for title again

I chose to go with the re-prompting method - give the user an error message and prompt again - as I think it's better UX than just failing outright.

## Testing

1. Pull down branch
2. Build: `make`
3. Run `gh issue create`
4. When prompted for a title, press enter
5. Observe change
6. When prompted for a title again, enter a non-blank title
7. Complete flow

