+func getSuggestions(client *http.Client, repo ghrepo.Interface) ([]string, error) {
+	limit := 1000
+	count, err := list.CountRepos(client, repo.RepoHost(), repo.RepoOwner(), "", false)
+	if err != nil {
+		return nil, err
+	}
+
+	if count > limit {
