+	}
+
+	options := list.FilterOptions{
+		Fields: []string{
+			"name",
+		},
+	}
+	res, err := list.ListRepos(client, repo.RepoHost(), limit, repo.RepoOwner(), options)
+	if err != nil {
+		return nil, err
+	}
