+
+	inputParams := map[string]interface{}{
+		"contentId": params["contentId"],
+		"projectId": params["projectId"],
+	}
+
+	variables := map[string]interface{}{
+		"input": inputParams,
+	}
+
+	result := struct {
+		AddItem struct {
+			Item Item
+		}
+	}{}
+
+	err := client.GraphQL(repo.RepoHost(), query, variables, &result)
+	if err != nil {
+		return nil, err
+	}
+
+	return &result.AddItem.Item, nil
