+			cs.WarningIcon(),
+			fullName)
+		return nil
+	}
+
+	err = archiveRepo(httpClient, repo)
+	if err != nil {
+		return fmt.Errorf("API called failed: %w", err)
+	}
+
+	if opts.IO.IsStdoutTTY() {
+		fmt.Fprintf(opts.IO.Out,
+			"%s Archived repository %s\n",
+			cs.SuccessIcon(),
+			fullName)
+	}
+
+	return nil
+}
