+ * @type {Record<string, { direct: string[]} | { descendant: string[] }>}
+ */
+const autoclosing_children = {
+	// based on http://developers.whatwg.org/syntax.html#syntax-tag-omission
+	li: { direct: ['li'] },
+	dt: { descendant: ['dt', 'dd'] },
+	dd: { descendant: ['dt', 'dd'] },
+	p: {
