+ *  str: MagicString;
+ *  analysis: import('../phases/types.js').ComponentAnalysis;
+ *  indent: string;
+ *  props: Array<{ local: string; exported: string; init: string; bindable: boolean; optional: boolean; type: string }>;
+ *  props_insertion_point: number;
+ *  has_props_rune: boolean;
