+		// TODO try to find out if we can use $derived.by instead?
+		if (is_block_stmt) {
+			state.str.update(
+				/** @type {number} */ (node.start),
+				start_end + 1,
+				`${state.run_name}(() => {`
+			);
+			const end = /** @type {number} */ (node.body.end);
+			state.str.update(end - 1, end, '});');
+		} else {
+			state.str.update(
+				/** @type {number} */ (node.start),
+				start_end,
+				`${state.run_name}(() => {\n${state.indent}`
