+					name = state.scope.generate(/** @type {any} */ (attr.value)[0].data);
+				} else {
+					const value =
+						attr.value !== true
+							? state.str.original.substring(
+									attr.value[0].start,
+									attr.value[attr.value.length - 1].end
+								)
+							: 'true';
+					slot_props += value === attr.name ? `${value}, ` : `${attr.name}: ${value}, `;
