+			}
+		}
+
+		slot_props += '}';
+		if (slot_props === '{ }') {
+			slot_props = '';
+		}
+
+		state.props.push({
+			local: name,
+			exported: name,
+			init: '',
+			bindable: false,
+			optional: true,
+			type: `import('svelte').${slot_props ? 'Snippet<[any]>' : 'Snippet'}`
+		});
