+    /// ```rust
+    /// # use clap::{App, Arg};
+    /// Arg::new("verbosity")
+    ///     .short('v')
+    ///     .max_occurrences(3);
+    /// ```
+    ///
+    /// Supplying less than the maximum number of arguments is allowed
+    ///
+    /// ```rust
+    /// # use clap::{App, Arg};
+    /// let res = App::new("prog")
