+    /// assert_eq!(m.occurrences_of("verbosity"), 3);
+    /// ```
+    ///
+    /// Supplying more than the maximum number of arguments is an error
+    ///
+    /// ```rust
+    /// # use clap::{App, Arg, ErrorKind};
+    /// let res = App::new("prog")
+    ///     .arg(Arg::new("verbosity")
