+impl<'a> PointedSpanArray<'a> {
+    #[inline]
+    #[must_use]
+    pub fn new_inner(value: &'a [Span], idx: usize) -> Option<Self> {
+        // check valid index, otherwise return none
+        _ = value.get(idx)?;
