index 0000000000..f6ae7bf42f
--- /dev/null
+++ b/src/pager.rs
@@ -0,0 +1,115 @@
+use shell_words::ParseError;
+use std::env;
+
+/// If we use a pager, this enum tells us from where we were told to use it.
+#[derive(Debug, PartialEq)]
+pub(crate) enum PagerSource {
+    /// From --config
+    Config,
+
+    /// From the env var BAT_PAGER
+    EnvVarBatPager,
+
+    /// From the env var PAGER
+    EnvVarPager,
+
+    /// No pager was specified, default is used
+    Default,
+}
+
+/// We know about some pagers, for example 'less'. This is a list of all pagers we know about
+#[derive(Debug, PartialEq)]
+pub(crate) enum PagerKind {
+    /// bat
+    Bat,
+
+    /// less
+    Less,
+
+    /// more
+    More,
+
+    /// most
+    Most,
+
+    /// A pager we don't know about
+    Unknown,
+}
+
+impl PagerKind {
+    fn from_bin(bin: &str) -> PagerKind {
+        use std::path::Path;
+
+        match Path::new(bin)
+            .file_stem()
+            .map(|s| s.to_string_lossy())
+            .as_deref()
+        {
+            Some("bat") => PagerKind::Bat,
+            Some("less") => PagerKind::Less,
+            Some("more") => PagerKind::More,
+            Some("most") => PagerKind::Most,
+            _ => PagerKind::Unknown,
+        }
+    }
+}
+
+/// A pager such as 'less', and from where we got it.
+#[derive(Debug)]
+pub(crate) struct Pager {
+    /// The pager binary
+    pub bin: String,
+
+    /// The pager binary arguments (that we might tweak)
+    pub args: Vec<String>,
+
+    /// What pager this is
+    pub kind: PagerKind,
+
+    /// From where this pager comes
+    pub source: PagerSource,
+}
+
+impl Pager {
+    fn new(bin: &str, args: &[String], kind: PagerKind, source: PagerSource) -> Pager {
+        Pager {
+            bin: String::from(bin),
+            args: args.to_vec(),
+            kind,
+            source,
+        }
+    }
+}
+
+/// Returns what pager to use, after looking at both config and environment variables.
+pub(crate) fn get_pager(config_pager: Option<&str>) -> Result<Option<Pager>, ParseError> {
+    let bat_pager = env::var("BAT_PAGER");
+    let pager = env::var("PAGER");
+
+    let (cmd, source) = match (config_pager, &bat_pager, &pager) {
+        (Some(config_pager), _, _) => (config_pager, PagerSource::Config),
+        (_, Ok(bat_pager), _) => (bat_pager.as_str(), PagerSource::EnvVarBatPager),
+        (_, _, Ok(pager)) => (pager.as_str(), PagerSource::EnvVarPager),
+        _ => ("less", PagerSource::Default),
+    };
+
+    let parts = shell_words::split(cmd)?;
+    match parts.split_first() {
+        Some((bin, args)) => {
+            let kind = PagerKind::from_bin(bin);
+
+            // 'more' and 'most' do not supports colors; automatically use 'less' instead
+            // if the problematic pager came from the generic PAGER env var
+            let no_color_support = kind == PagerKind::More || kind == PagerKind::Most;
+            let use_less_instead = no_color_support && source == PagerSource::EnvVarPager;
+
+            Ok(Some(if use_less_instead {
+                let no_args = vec![];
+                Pager::new("less", &no_args, PagerKind::Less, PagerSource::EnvVarPager)
+            } else {
+                Pager::new(bin, args, kind, source)
+            }))
+        }
+        None => Ok(None),
+    }
+}

style: add component 'rule' for horizontal file delimiter

Closes #1163 

Adds a new style argument `rule` (open to bikeshedding on the name), which adds a simple horizontal ruled line between files.

This line takes the place of padding (an empty line) that would otherwise be added anyway to delimit files, and is the same color as the grid style.

A couple of questions I had while implementing this:

- Should this style component be enabled by the `full` argument? This PR does not make it enabled by the `full` argument, becuase:
  - I don't think it is semantically correct (in my mind, `rule` is a subset of `grid` already)
  - it looks horrible
  - it would be a breaking change
- ~The snapshot tests do not cover the case of printing multiple files - should they?~
  - ~Currently, coverage of this new feature and the existing feature of `bat` delimiting files with whitespace is not covered. Happy to update the tests to cover this case, but it would probably be better in it's own PR?~
  - It's covered in the integration tests, added a new case there

---

Output examples:

```log
$ bat LICENSE-MIT LICENSE-MIT --style=rule,header,numbers
     File: LICENSE-MIT
   1 Copyright (c) 2018-2020 bat-developers (https://github.com/sharkdp/bat).
   2
...
  18 OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
  19 SOFTWARE.
─────────────────────────────────────────────────────────────────────────────────────────────────────────────
     File: LICENSE-MIT
   1 Copyright (c) 2018-2020 bat-developers (https://github.com/sharkdp/bat).
   2
...
  18 OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
  19 SOFTWARE.
```

![image](https://user-images.githubusercontent.com/12255914/95229627-b3842d80-07f8-11eb-96b1-e914287e80d3.png)


