+export default function ToggleGroupUsage() {
+  const [value, setValue] = React.useState('bold');
+  const [values, setValues] = React.useState([value]);
+  return (
+    <JoyUsageDemo
+      componentName="ToggleButtonGroup"
+      data={[
+        {
+          propName: 'variant',
+          knob: 'select',
+          defaultValue: 'outlined',
+          options: ['plain', 'outlined', 'soft', 'solid'],
+        },
+        {
+          propName: 'color',
+          knob: 'color',
+          defaultValue: 'neutral',
+        },
+        {
+          propName: 'size',
+          knob: 'radio',
+          options: ['sm', 'md', 'lg'],
+          defaultValue: 'md',
+        },
+        {
+          propName: 'children',
+          defaultValue: `<Button />
+  <IconButton />
+  <IconButton />`,
+        },
+      ]}
+      renderDemo={(props) => (
+        <Box sx={{ display: 'flex', gap: 2 }}>
+          <ToggleButtonGroup
+            value={props.exclusive ? value : values}
+            onChange={(event, newValue) => {
+              if (Array.isArray(newValue)) {
+                setValues(newValue);
+              } else {
+                setValue(newValue);
+              }
+            }}
+            {...props}
+          >
+            <Button value="bold">Bold</Button>
+            <IconButton value="italic">
+              <FormatItalicIcon />
+            </IconButton>
+            <IconButton value="underlined">
+              <FormatUnderlinedIcon />
+            </IconButton>
+          </ToggleButtonGroup>
+        </Box>
+      )}
