+            { value: 25 },
+            { value: 50 },
+            { value: 75 },
+            { value: 100 },
+          ]}
+          valueLabelFormat={valuetext}
+          valueLabelDisplay="on"
+        />
+      </Box>
+    </ThemeProvider>
+  );
+}
