+                <FormControlLabel
+                  value="column"
+                  control={<Radio />}
+                  label="column"
+                />
+                <FormControlLabel
+                  value="column-reverse"
+                  control={<Radio />}
+                  label="column-reverse"
+                />
+              </RadioGroup>
+            </FormControl>
+          </Grid>
+          <Grid item xs={12}>
+            <FormControl component="fieldset">
+              <FormLabel component="legend">alignItems</FormLabel>
+              <RadioGroup
+                row
+                name="alignItems"
+                aria-label="align items"
+                value={alignItems}
+                onChange={(event) => {
+                  setAlignItems(event.target.value);
+                }}
+              >
+                <FormControlLabel
+                  value="flex-start"
+                  control={<Radio />}
+                  label="flex-start"
+                />
+                <FormControlLabel
+                  value="center"
+                  control={<Radio />}
+                  label="center"
+                />
+                <FormControlLabel
+                  value="flex-end"
+                  control={<Radio />}
+                  label="flex-end"
+                />
+                <FormControlLabel
+                  value="stretch"
+                  control={<Radio />}
+                  label="stretch"
+                />
+                <FormControlLabel
+                  value="baseline"
+                  control={<Radio />}
+                  label="baseline"
+                />
+              </RadioGroup>
+            </FormControl>
+          </Grid>
+          <Grid item xs={12}>
+            <FormControl component="fieldset">
+              <FormLabel component="legend">justifyContent</FormLabel>
+              <RadioGroup
+                row
+                name="justifyContent"
+                aria-label="justifyContent"
+                value={justifyContent}
+                onChange={(event) => {
+                  setJustifyContent(event.target.value);
+                }}
+              >
+                <FormControlLabel
+                  value="flex-start"
+                  control={<Radio />}
+                  label="flex-start"
+                />
+                <FormControlLabel
+                  value="center"
+                  control={<Radio />}
+                  label="center"
+                />
+                <FormControlLabel
+                  value="flex-end"
+                  control={<Radio />}
+                  label="flex-end"
+                />
+                <FormControlLabel
+                  value="space-between"
+                  control={<Radio />}
+                  label="space-between"
+                />
+                <FormControlLabel
+                  value="space-around"
+                  control={<Radio />}
+                  label="space-around"
+                />
+                <FormControlLabel
+                  value="space-evenly"
+                  control={<Radio />}
+                  label="space-evenly"
+                />
+              </RadioGroup>
+            </FormControl>
+          </Grid>
+          <Grid item xs={12}>
+            <FormControl component="fieldset">
+              <FormLabel component="legend">spacing</FormLabel>
+              <RadioGroup
+                row
