@@ -0,0 +1,33 @@
+{
+  "componentDescription": "Modal is a lower-level construct that is leveraged by the following components:\n\n- [Dialog](/api/dialog/)\n- [Drawer](/api/drawer/)\n- [Menu](/api/menu/)\n- [Popover](/api/popover/)\n\nIf you are creating a modal dialog, you probably want to use the [Dialog](/api/dialog/) component\nrather than directly using Modal.\n\nThis component shares many concepts with [react-overlays](https://react-bootstrap.github.io/react-overlays/#modals).",
+  "propDescriptions": {
+    "BackdropComponent": "A backdrop component. This prop enables custom backdrop rendering.",
+    "BackdropProps": "Props applied to the <a href=\"/api/backdrop-unstyled/\"><code>Backdrop</code></a> element.",
+    "children": "A single child content element.<br>⚠️ <a href=\"/guides/composition/#caveat-with-refs\">Needs to be able to hold a ref</a>.",
+    "classes": "Override or extend the styles applied to the component. See <a href=\"#css\">CSS API</a> below for more details.",
+    "closeAfterTransition": "When set to true the Modal waits until a nested Transition is completed before closing.",
+    "component": "The component used for the root node. Either a string to use a HTML element or a component.",
+    "components": "The components used for each slot inside the Modal. Either a string to use a HTML element or a component.",
+    "componentsProps": "The props used for each slot inside the Modal.",
+    "container": "An HTML element or function that returns one. The <code>container</code> will have the portal children appended to it.<br>By default, it uses the body of the top-level document object, so it&#39;s simply <code>document.body</code> most of the time.",
+    "disableAutoFocus": "If <code>true</code>, the modal will not automatically shift focus to itself when it opens, and replace it to the last focused element when it closes. This also works correctly with any modal children that have the <code>disableAutoFocus</code> prop.<br>Generally this should never be set to <code>true</code> as it makes the modal less accessible to assistive technologies, like screen readers.",
+    "disableEnforceFocus": "If <code>true</code>, the modal will not prevent focus from leaving the modal while open.<br>Generally this should never be set to <code>true</code> as it makes the modal less accessible to assistive technologies, like screen readers.",
+    "disableEscapeKeyDown": "If <code>true</code>, hitting escape will not fire the <code>onClose</code> callback.",
+    "disablePortal": "The <code>children</code> will be under the DOM hierarchy of the parent component.",
+    "disableRestoreFocus": "If <code>true</code>, the modal will not restore focus to previously focused element once modal is hidden.",
+    "disableScrollLock": "Disable the scroll lock behavior.",
+    "hideBackdrop": "If <code>true</code>, the backdrop is not rendered.",
+    "keepMounted": "Always keep the children in the DOM. This prop can be useful in SEO situation or when you want to maximize the responsiveness of the Modal.",
+    "onBackdropClick": "Callback fired when the backdrop is clicked.",
+    "onClose": "Callback fired when the component requests to be closed. The <code>reason</code> parameter can optionally be used to control the response to <code>onClose</code>.<br><br><strong>Signature:</strong><br><code>function(event: object, reason: string) =&gt; void</code><br><em>event:</em> The event source of the callback.<br><em>reason:</em> Can be: <code>&quot;escapeKeyDown&quot;</code>, <code>&quot;backdropClick&quot;</code>.",
+    "open": "If <code>true</code>, the component is shown."
+  },
+  "classDescriptions": {
+    "root": { "description": "Styles applied to the root element." },
+    "hidden": {
+      "description": "Styles applied to {{nodeName}} if {{conditions}}.",
+      "nodeName": "the root element",
+      "conditions": "the <code>Modal</code> has exited"
+    }
+  }
+}
